import {Simulation,pathPoint,clamp} from './simulation.js';
import {RaceScene} from './scene.js';
import {preloadModels} from './assets.js';
const $=s=>document.querySelector(s);
const keys=new Set(),touch=new Set();let sim=new Simulation('aquarium'),view,pausedFrom='racing',last=0,accumulator=0,lastEvent=null,toastUntil=0,activeWorld='aquarium',audioOn=false,audioContext=null,osc=null,gain=null,deferredInstall=null;
const timeString=t=>`${String(Math.floor(t/60)).padStart(2,'0')}:${(t%60).toFixed(1).padStart(4,'0')}`;
function fatal(error){console.error(error);$('#fatal').hidden=false;$('#menu').hidden=true;$('#start').disabled=true;}
$('#start').disabled=true;
$('#start').textContent='WERELD LADEN…';
const modelResults=await preloadModels();
if(modelResults.some(r=>r.status==='rejected'))console.warn('Some GLB models could not be loaded; original procedural model fallback is active.');
$('#start').disabled=false;
$('#start').innerHTML='START DE RACE <span>→</span>';
try{view=new RaceScene($('#game'));view.setWorld(sim);}catch(e){fatal(e);}
function setMode(mode){activeWorld=mode;sim=new Simulation(mode);document.body.classList.toggle('terrarium',mode==='terrarium');document.querySelectorAll('[data-world]').forEach(b=>{const selected=b.dataset.world===mode;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected));});$('#habitat-label').innerHTML=mode==='aquarium'?'<span>HABITAT 01 / AQUARIUM</span><strong>Diep Water</strong><small>Guppies · piranha’s · een slechte timing</small>':'<span>HABITAT 02 / TERRARIUM</span><strong>Wildgroei</strong><small>Spinnen · slangen · de tong des doods</small>';view.setWorld(sim);$('#vehicle-hint').textContent=mode==='aquarium'?'Q / E stijgen & duiken':'Zand vertraagt · keien laten je stuiteren';document.querySelectorAll('[data-control="rise"],[data-control="dive"]').forEach(b=>b.hidden=mode!=='aquarium');}
function startRace(){closeDialogs();keys.clear();touch.clear();sim=new Simulation(activeWorld);sim.start();lastEvent=null;view.setWorld(sim);document.body.classList.add('racing');$('#menu').hidden=true;$('#habitat-label').hidden=true;$('#menu-footer').hidden=true;$('#hud').hidden=false;$('#pause').hidden=false;$('#touch-controls').hidden=!matchMedia('(pointer:coarse)').matches;$('#countdown').textContent='3';accumulator=0;if(audioOn)ensureAudio();}
function menu(){closeDialogs();keys.clear();touch.clear();document.body.classList.remove('racing');$('#hud').hidden=true;$('#pause').hidden=true;$('#touch-controls').hidden=true;$('#menu').hidden=false;$('#habitat-label').hidden=false;$('#menu-footer').hidden=false;setMode(activeWorld);}
function closeDialogs(){document.querySelectorAll('dialog[open]').forEach(d=>d.close());}
function pause(){if(!['racing','countdown'].includes(sim.phase))return;pausedFrom=sim.phase;sim.phase='paused';keys.clear();touch.clear();$('#pause-dialog').showModal();}
function resume(){if(sim.phase!=='paused')return;$('#pause-dialog').close();sim.phase=pausedFrom;accumulator=0;}
function finish(){if($('#results-dialog').open)return;const ranking=sim.ranking(),place=ranking.findIndex(r=>r.id===0)+1;$('#result-title').textContent=place===1?'Bovenaan de voedselketen.':`P${place}. Je hebt het overleefd.`;$('#result-time').textContent=`${sim.config.title} · 3 rondes · ${timeString(sim.racers[0].finishTime)}`;$('#standings').replaceChildren(...ranking.map((r,i)=>{const li=document.createElement('li');li.className=r.id===0?'you':'';const a=document.createElement('span'),b=document.createElement('span');a.textContent=`${i+1}. ${r.name}`;b.textContent=r.finished?timeString(r.finishTime):`Ronde ${Math.min(r.lap,3)} · nog onderweg`;li.append(a,b);return li;}));$('#results-dialog').showModal();beep(660,.3);keys.clear();touch.clear();}
document.querySelectorAll('[data-world]').forEach(b=>b.addEventListener('click',()=>setMode(b.dataset.world)));
$('#start').addEventListener('click',startRace);$('#help').addEventListener('click',()=>$('#info-dialog').showModal());document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));$('#pause').addEventListener('click',pause);$('#resume').addEventListener('click',resume);$('#restart').addEventListener('click',startRace);$('#race-again').addEventListener('click',startRace);$('#back-menu').addEventListener('click',menu);$('#choose-world').addEventListener('click',menu);$('#food').addEventListener('click',()=>sim.dropFood());$('#touch-food').addEventListener('click',()=>sim.dropFood());$('#pause-dialog').addEventListener('cancel',e=>{e.preventDefault();resume();});$('#results-dialog').addEventListener('cancel',e=>{e.preventDefault();menu();});
const controlCodes=['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space','KeyW','KeyA','KeyS','KeyD','KeyQ','KeyE','KeyR','ShiftLeft','ShiftRight'];
addEventListener('keydown',e=>{if(e.code==='Escape'&&!$('#info-dialog').open&&!$('#results-dialog').open){e.preventDefault();if(sim.phase==='paused')resume();else pause();return;}if(!['racing','countdown'].includes(sim.phase))return;if(controlCodes.includes(e.code)){e.preventDefault();keys.add(e.code);}if(!e.repeat&&e.code==='Space')sim.dropFood();if(!e.repeat&&e.code==='KeyR'&&sim.phase==='racing')sim.resetRacer();});
addEventListener('keyup',e=>keys.delete(e.code));addEventListener('blur',()=>{keys.clear();touch.clear();pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden)pause();});
document.querySelectorAll('[data-control]').forEach(b=>{const name=b.dataset.control;b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);touch.add(name);b.classList.add('active');});for(const type of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(type,()=>{touch.delete(name);b.classList.remove('active');});});
function input(){const down=(...ks)=>ks.some(k=>keys.has(k));return {throttle:Number(down('KeyW','ArrowUp')||touch.has('forward'))-Number(down('KeyS','ArrowDown')||touch.has('back')),steer:Number(down('KeyD','ArrowRight')||touch.has('right'))-Number(down('KeyA','ArrowLeft')||touch.has('left')),vertical:Number(down('KeyQ')||touch.has('rise'))-Number(down('KeyE')||touch.has('dive')),boost:down('ShiftLeft','ShiftRight')||touch.has('boost')};}
function ensureAudio(){if(!audioContext){audioContext=new(window.AudioContext||window.webkitAudioContext)();osc=audioContext.createOscillator();gain=audioContext.createGain();osc.type='triangle';gain.gain.value=0;osc.connect(gain).connect(audioContext.destination);osc.start();}audioContext.resume();}
function beep(freq,duration=.12){if(!audioOn||!audioContext)return;const o=audioContext.createOscillator(),g=audioContext.createGain();o.frequency.value=freq;g.gain.setValueAtTime(.045,audioContext.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+duration);o.connect(g).connect(audioContext.destination);o.start();o.stop(audioContext.currentTime+duration);}
$('#sound').addEventListener('click',()=>{audioOn=!audioOn;$('#sound').style.color=audioOn?'var(--lime)':'';$('#sound').setAttribute('aria-label',audioOn?'Geluid uitschakelen':'Geluid inschakelen');if(audioOn)ensureAudio();else if(gain)gain.gain.value=0;});
const map=$('#minimap').getContext('2d');
function drawMap(){const w=220,h=170;map.clearRect(0,0,w,h);const project=p=>[110+p.x*2.1,85+p.z*2.1];map.beginPath();for(let i=0;i<=90;i++){const [x,y]=project(pathPoint(sim.mode,i/90,sim.time));if(i===0)map.moveTo(x,y);else map.lineTo(x,y);}map.strokeStyle='#c4ddb740';map.lineWidth=8;map.stroke();map.lineWidth=1;map.strokeStyle='#c4ddb799';map.stroke();const gate=project(sim.gatePoint(sim.racers[0].gate));map.strokeStyle='#ccff77';map.lineWidth=2;map.beginPath();map.arc(...gate,6,0,Math.PI*2);map.stroke();for(const a of sim.animals){const [x,y]=project(a);map.fillStyle=a.target?'#ffb951':'#ba8076';map.fillRect(x-2,y-2,4,4);}for(const r of [...sim.racers].reverse()){const [x,y]=project(r);map.fillStyle=r.id===0?'#e0ff89':`#${sim.config.colors[r.id].toString(16)}`;map.beginPath();map.arc(x,y,r.id===0?4:3,0,Math.PI*2);map.fill();if(!r.id){map.beginPath();map.moveTo(x,y);map.lineTo(x+Math.sin(r.yaw)*9,y+Math.cos(r.yaw)*9);map.strokeStyle='#e0ff89';map.stroke();}}}
let hudTime=0;
function updateHud(dt){hudTime+=dt;const r=sim.racers[0];if(sim.phase==='countdown')$('#countdown').textContent=Math.ceil(sim.countdown);else if(sim.phase==='racing'&&sim.elapsed<.7)$('#countdown').textContent='GO!';else $('#countdown').textContent='';if(hudTime<.08)return;hudTime=0;$('#speed').textContent=Math.round(Math.abs(r.speed)*3);$('#time').textContent=timeString(sim.elapsed);$('#lap').textContent=`${Math.min(r.lap,3)} / 3`;$('#position').textContent=sim.ranking().findIndex(q=>q.id===0)+1;$('#boost-meter').style.width=`${r.boost}%`;$('#food-count').textContent=`${r.food} porties · Spatie`;$('#food').disabled=r.food===0||r.foodCooldown>0;$('#gate-label').textContent=`CHECKPOINT ${r.gate+1} / ${sim.config.gates}`;const ev=sim.events.at(-1);if(ev&&ev!==lastEvent){lastEvent=ev;$('#toast').textContent=ev.text;toastUntil=sim.time+3;beep(ev.type==='hit'?110:ev.type==='food'?330:520);}$('#toast').classList.toggle('visible',sim.time<toastUntil);drawMap();}
function frame(t){requestAnimationFrame(frame);if(!view)return;const dt=Math.min(.1,(t-(last||t))/1000);last=t;accumulator+=dt;const controls=input();while(accumulator>=1/60){sim.step(1/60,controls);accumulator-=1/60;}view.update(sim,Math.min(dt,1/20),sim.phase==='menu');if(sim.phase!=='menu')updateHud(dt);if(sim.phase==='finished')finish();if(audioContext&&audioOn){const running=sim.phase==='racing';osc.frequency.setTargetAtTime(50+Math.abs(sim.racers[0].speed)*7,audioContext.currentTime,.1);gain.gain.setTargetAtTime(running?.022:0,audioContext.currentTime,.1);}}
if(view)requestAnimationFrame(frame);
addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e;$('#install').hidden=false;});$('#install').addEventListener('click',async()=>{if(deferredInstall){await deferredInstall.prompt();deferredInstall=null;$('#install').hidden=true;}});addEventListener('appinstalled',()=>$('#install').hidden=true);
if('serviceWorker'in navigator){addEventListener('load',()=>navigator.serviceWorker.register('./sw.js',{scope:'./'}).catch(e=>console.warn('Offline cache unavailable',e)));}
